window.NOTES={"version":69,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":4,"chapter":7,"section":"7.1","type":"单选","topic":"多媒体特征","title":"多媒体强调集成、交互与实时处理","trigger":"题目要求从若干描述中找出不属于多媒体技术特征的一项。","conclusion":"多媒体技术通常具有多样性、集成性、交互性和实时性，“单一性”与其核心含义相反。","points":["多样性指文本、图形、图像、音频、动画和视频等媒体。","集成性指多种媒体及软硬件协同处理。","交互性允许用户影响内容呈现和系统反馈。","音视频连续播放和及时响应用户动作强调实时性；多种媒体存在强调多样性/集成性，操作能改变反馈强调交互性。","文字同样属于多媒体元素；远程医疗、教学网页等可综合文本、图像、声音和视频，但不是所有网页都必定同时包含全部媒体类型。","媒体是承载或呈现信息的形式；数字媒体用数字编码表示内容。多媒体技术由计算机把多种媒体组织、处理和呈现，并支持适当的交互与时序控制，不只是把一张图片与一段声音放在一起。","数字化先把需要表示的信息变成可处理的数据：图像可用像素网格记录颜色，声音可按时间取样并记录幅度。编码说明怎样表示，压缩说明怎样减少数据量；数字化不以“必须有损压缩”为前提。"],"boundary":"并非每个多媒体作品都具备相同程度的实时性或交互性，教材概括描述的是技术特征。","id":"y2026q4","sources":[{"year":2026,"q":4,"type":"单选"},{"year":2022,"q":49,"type":"填空"},{"year":2021,"q":17,"type":"单选","page":4}],"keys":["2026-4","2022-49","2021-17"],"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"VR把多感知、交互与实时反馈组合起来，但普通多媒体或3D画面不因此自动成为VR。"},{"id":"y2020q38","label":"帧、帧率与视频连续感","reason":"连续音视频体现实时性；帧与帧率笔记提供区分连续播放要求和媒体种类多少的实例。"}],"pointGroups":[{"title":"先理解媒体与数字化","indices":[5,0,6]},{"title":"从情景判断技术特征","indices":[1,2,3,4]}],"pointPresentation":{"1":{"title":"集成性看协同处理","navigationLabel":"集成性看协同处理"},"3":{"title":"实时性看连续播放与及时响应","navigationLabel":"实时性看连续播放与及时响应"},"5":{"title":"媒体、多媒体与数字表示","navigationLabel":"媒体、多媒体与数字表示"},"6":{"title":"数字化先于压缩","navigationLabel":"数字化先于压缩"}}},{"q":19,"chapter":7,"section":"7.1","type":"单选","topic":"图形图像","title":"矢量图形放大通常不失真，位图由像素构成","trigger":"题目比较计算机图形与数字图像放大后的表现。","conclusion":"矢量图形由数学对象描述，缩放时可重新计算边界；位图由固定像素阵列构成，过度放大会出现锯齿或像素块。","points":["Logo、图标和线稿常适合矢量表示。","照片和连续色调画面通常适合位图表示。","矢量图最终显示到屏幕或打印时仍要栅格化输出。","判断缩放先看实际内容：矢量路径可按几何描述重新绘制，位图缩放需要重新取样或显示已有像素。SVG等文件也能嵌入位图照片，文件中这部分不会因装在矢量文件里就获得无限细节。"],"boundary":"矢量并非任何情况下文件都更小，也不是所有“绘制出来的图”都自动属于矢量图。","id":"y2023q19","sources":[{"year":2023,"q":19,"type":"单选"}],"keys":["2023-19"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"位图放大受固定像素阵列约束，可进一步从像素数和每像素位数理解图像表示。"},{"id":"y2024q43","label":"锐化增强边缘和局部细节","reason":"位图放大或缺少细节后，锐化只能增强边缘清晰感，不能把缺失像素信息变回来。"}],"pointGroups":[{"title":"先辨对象，再预测缩放","indices":[0,1,3]},{"title":"交付时还要看输出方式","indices":[2]}],"pointPresentation":{"0":{"title":"位图和矢量保存什么","navigationLabel":"位图和矢量保存什么"},"3":{"title":"混合内容不能按扩展名一概判断","navigationLabel":"混合内容不能按扩展名一概判断"}}},{"q":27,"chapter":7,"section":"7.1","type":"多选","topic":"媒体元素与图像","title":"多媒体元素、数字图像与颜色深度","trigger":"真题从媒体种类、系统构成、压缩和颜色深度对数据量的影响考查多媒体基础。","conclusion":"多媒体包含文本、图形、图像、音频、动画和视频。位图由像素组成；估算未压缩像素数据量时，要分清每通道位深、每像素位数，以及 bit 与 B。","points":["多媒体系统把不同媒体组织在一起，并依靠硬件与软件完成采集、处理、存储和输出；声音等模拟信号需先数字化。","位图的宽×高给出像素总数。若每像素用 b 位，紧密存放的像素数据量为宽×高×b bit，换成 B 还要除以 8。","“8 位”须看指什么：RGB 每通道 8 位时，每像素是 3×8＝24 位；RGBA 每通道 8 位时为 32 位，其中 A 表示透明度。","索引色保存调色板编号。例如每像素 8 位可表示最多 256 个索引；像素区按 8 位计算，调色板另占空间。","像素数与表示方式相同时，增加每像素位数会增加未压缩像素数据量；实际文件还受压缩、文件头、元数据、调色板和行填充等影响。","MP3 是有损音频编码；MP4 是可承载视频、音频等内容的容器，不能仅凭扩展名判断媒体是否无损。","Flash动画属于动画创作与表现形式，不是一种数字视频无损压缩算法；动画内容可以另行导出为视频。","像素是位图中的采样单元；“宽1200像素、高800像素”说明共960000个像素。图像尺寸、显示缩放比例与实际文件字节数是不同量；把预览放大到200%不等于文件的像素数翻倍。","若每像素的b位全部用于颜色或灰度编号，理论最多表示2ᵇ种状态：1位为2种，8位为256种，RGB每通道8位共24位为16777216种RGB组合。RGBA的第4个8位通道表示透明程度，不应直接说成2³²种可见颜色。","完整算例：800×600像素、RGB 24位、未压缩且只计紧密像素数据，先得480000像素，再乘24得11520000 bit，除8得1440000 B，即1.44 MB，约1.373 MiB。题目若约定KB按1024 B，按该约定换算并注明；不要把bit直接当Byte。","PPI表示每英寸安排多少图像像素；1200像素宽按300 PPI打印是4英寸，按150 PPI是8英寸。关闭重新采样时改变PPI不会新增像素。打印机DPI描述设备每英寸可印的点，与图像PPI不是同一个参数。","按时间表现可分静态图像和动态图像：单幅照片是静态，连续呈现多幅画面可形成动画或视频。这个维度不同于位图/矢量；动画不一定是矢量，GIF动画也可以由多幅位图组成。"],"boundary":"该公式估算像素区，不直接等于磁盘上的图像文件大小。颜色通道位数描述颜色表示，Alpha 描述透明度；RGBA 的 32 位不能直接说成 2³² 种 RGB 颜色。","id":"y2020q27","sources":[{"year":2020,"q":27,"type":"多选"},{"year":2023,"q":38,"type":"判断"},{"year":2024,"q":3,"type":"单选"},{"year":2024,"q":23,"type":"多选"}],"keys":["2020-27","2023-38","2024-3","2024-23"],"comparison":{"headers":["示例表示方式","每像素位数","100×100 像素的数据量"],"rows":[["8 位灰度","8 bit","10,000 B"],["RGB：每通道 8 位","24 bit","30,000 B"],["RGBA：每通道 8 位","32 bit","40,000 B"],["8 位索引色","8 bit","像素区 10,000 B，另计调色板"]]},"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"像素数据量计算要将每像素位数转换为字节，并按题设区分MB与MiB。"},{"id":"y2020q17","label":"RGB与CMYK的适用场景","reason":"RGB通道参与颜色表示，CMYK面向印刷；颜色模型与每通道位深是不同判断维度。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"实际文件还受压缩和容器影响，不能把宽×高×位深的原始像素量直接当作JPEG或PNG文件大小。"}],"pointGroups":[{"title":"像素、颜色与时间表现","indices":[7,8,2,3,11]},{"title":"计算数据量并区分打印尺寸","indices":[1,9,4,10]},{"title":"回到媒体、编码与容器","indices":[0,5,6]}],"pointPresentation":{"7":{"title":"像素尺寸与预览缩放","navigationLabel":"像素尺寸与预览缩放"},"8":{"title":"颜色数与Alpha的边界","navigationLabel":"颜色数与Alpha的边界"},"9":{"title":"从bit到B的完整图像算例","navigationLabel":"从bit到B的完整图像算例"},"10":{"title":"PPI、打印尺寸与DPI","navigationLabel":"PPI、打印尺寸与DPI"},"11":{"title":"静态、动态不等于位图、矢量","navigationLabel":"静态、动态不等于位图、矢量"}},"searchAliases":["图像数据量","PPI","DPI","静态图像","动态图像","Alpha"]},{"q":28,"chapter":7,"section":"7.1","type":"多选","topic":"数字媒体数据量","title":"采样、位深、编码与冗余共同决定数字媒体数据量","trigger":"真题综合考查音频采样率、MIDI与波形、JPEG有损压缩及图像空间冗余。","conclusion":"未压缩 PCM 音频的数据量由采样率、量化位数、声道数和时长共同决定；采样率管每秒采多少次，量化位数管每次样值用多少位表示。","points":["采样在时间轴上取点，量化把每个点的幅度归入有限档位，编码再用二进制表示档位。采样率是每声道每秒取点次数；量化位数b可表示2ᵇ个档位，例如2位可用00、01、10、11表示4档。","先数样值：每声道样值数=采样率×秒数；再乘声道数得到全部样值数，乘每样值位数得到bit，最后除8换成B。因此PCM码率=采样率×位数×声道数，数据量=码率×秒数÷8。","44.1 kHz、16 位、单声道、120 秒的 PCM 数据量是 44,100×16×1×120÷8＝10,584,000 B；改成双声道则为 21,168,000 B，均未计文件头。","压缩音频若已知平均码率，可按平均码率×时长÷8 估算编码数据量；不能把 PCM 公式直接当作 MP3 等压缩文件的大小公式。","MIDI 主要记录音符、力度、音色选择等演奏事件，不直接保存录制的声音波形；同一 MIDI 用不同音源播放，声音可能不同。","压缩可利用数据冗余；有损压缩还可能舍弃部分感知信息。图像相邻像素的相似属于空间冗余，JPEG 通常采用有损压缩。","用小数值检查单位：每声道每秒取4个样值、每样值8位、双声道、持续3秒，共4×3×2=24个样值，24×8=192 bit=24 B。这个低采样率例子只用于数数据，真实音频计算方法相同。","单声道是一条声音通道；双声道通常用左右两条通道形成声场信息。PCM按每声道每秒样值数计算，所以相同采样率、存储位数和时长下，双声道的数据量是单声道的2倍；编辑工程的轨道数不等于导出声道数。","上述简化公式按量化位数与每样值实际存储位数相同的未压缩PCM计算。若20个有效位放在24位存储单元中，应按24位计算容量；文件头、对齐及其他开销另计。","做题先固定条件：提高采样率会增加单位时间样值数，但不能单独保证音质更好。2021年第38题配套填空为“采样”；2023年第28题中有关采样、音质和容量的判断，应联系信号来源、位深、声道与编码条件，不能推广到任意压缩文件。"],"boundary":"单独提高采样率不保证听起来更好，音质还受信号来源、量化、编码和播放设备影响。数据量的倍数关系须固定其他条件；kHz 中的 k 按 1000 计算，B 与 bit 相差 8 倍。","id":"y2024q32","sources":[{"year":2023,"q":28,"type":"多选"},{"year":2024,"q":32,"type":"判断"},{"year":2022,"q":17,"type":"单选"},{"year":2022,"q":38,"type":"判断"},{"year":2021,"q":38,"type":"填空","page":6}],"keys":["2023-28","2024-32","2022-17","2022-38","2021-38"],"comparison":{"headers":["量","说明","常用单位"],"rows":[["采样率","每声道每秒采样多少次","Hz、kHz"],["量化位数","每个样值用多少位表示","bit/样值"],["声道数","同时记录多少路声音","单声道 1、双声道 2"],["PCM 码率","采样率×量化位数×声道数","bit/s"],["压缩音频平均码率","编码后平均每秒的数据位数","bit/s、kbit/s"]]},"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"采样率乘位深和声道数得到bit/s，乘时长后还要除以8才能换成B。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"PCM原始数据公式、MP3平均码率估算和WAV容器判断必须分别使用，MIDI也不是录音波形。"},{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"算出音频码率和数据量后，可将其作为网络传输计算的输入，同时区分媒体码率与链路有效速率。"}],"pointGroups":[{"title":"先分采样、量化和声道","indices":[0,7]},{"title":"按样值推导PCM容量","indices":[8,1,6,2]},{"title":"压缩、事件与题目条件","indices":[3,4,5,9]}],"workedExamples":[{"year":2024,"q":32,"questionSummary":"同一声音、同样时长，提高采样频率会怎样影响数据量。","reasoning":["采样频率表示每秒取得多少个采样点；时间相同而采样频率增加，采样点数增加。","在量化位数、声道数与未压缩表示相同的前提下，数据量=采样率×位深×声道数×时长÷8。","若比较的是不同压缩设置的成品文件，还需考虑编码方式，不能只用采样率断定大小。"],"pitfall":"漏掉位深、声道及压缩条件，把单因素结论推广成所有音频文件。","transfer":"教学示例：其他条件不变，采样率翻倍会使未压缩PCM样本数据量翻倍。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"原卷完整题干与配套答案已核（v66）；配套答案未认定为官方","historicalVersionNote":""}],"pointPresentation":{"0":{"title":"采样在时间上取点，量化在幅度上分档","navigationLabel":"采样在时间上取点，量化在幅度上分档"},"6":{"title":"先用小数值验证单位","navigationLabel":"先用小数值验证单位"},"7":{"title":"声道数不等于轨道数","navigationLabel":"声道数不等于轨道数"},"8":{"title":"有效位深与实际存储宽度","navigationLabel":"有效位深与实际存储宽度"},"9":{"title":"采样判断题要固定哪些条件","navigationLabel":"采样判断题要固定哪些条件"}}},{"q":38,"chapter":7,"section":"7.1","type":"填空","topic":"视频","title":"帧、帧率与视频连续感","trigger":"题目要求指出视频信息的基本图像单位。","conclusion":"视频由连续图像帧组成，帧是构成视频画面的基本单位。","points":["帧率表示每秒显示的帧数，常用fps；固定25 fps播放4秒共有25×4=100帧。帧数回答有多少幅画面，帧率回答每秒播放多少幅。","相同分辨率、每像素位数和时长下，提高帧率会增加原始画面数据量，通常也让运动变化更平滑；它不直接增加单帧的像素数。","若每帧是紧密存放、未压缩的同规格位图，画面数据量=宽×高×每像素位数×帧率×秒数÷8 B。例如100×100像素、24 bit、25 fps、4秒，得到3,000,000 B。","帧率用fps表示每秒多少幅画面；码率用bit/s表示每秒多少数据。若音视频平均总码率为2 Mbit/s、时长10秒，编码数据约为2000000×10÷8=2500000 B=2.5 MB，尚未计额外封装开销；总码率已经包含音轨时，不再重复乘声道数。","视频常从连续拍摄的画面获得，动画可由绘制或计算的画面形成；两者最终都能按时间呈现帧。二维动画主要组织平面对象，三维动画还要描述空间对象与视角。关键帧给出重要时刻的状态，补间按设定计算中间状态，并不是每一帧都必须手工重画。"],"boundary":"视频公式这里只计算原始画面，不含音轨、文件头和压缩影响；压缩文件已知平均总码率时可按码率×时长÷8估算。“超过24帧人眼就完全无法区分”不是严格生理定律。 网页演示的2秒终点只表示运动结束，不额外计入总帧数。","id":"y2020q38","sources":[{"year":2020,"q":38,"type":"填空"}],"keys":["2020-38"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"先估算一帧的像素数据，再结合帧率与时长理解未压缩视频数据量的增长。"},{"id":"y2023q18","label":"流媒体强调边传输边播放和连续时序","reason":"帧的连续播放需要数据及时到达；流媒体缓冲可解释帧率之外的网络卡顿原因。"}],"pointGroups":[{"title":"从帧理解连续画面","indices":[0,1,4]},{"title":"分别计算原始像素量和压缩码率","indices":[2,3]}],"pointPresentation":{"0":{"title":"帧与帧率的对象","navigationLabel":"帧与帧率的对象"},"3":{"title":"码率不是帧率","navigationLabel":"码率不是帧率"},"4":{"title":"视频、动画与关键帧","navigationLabel":"视频、动画与关键帧"}},"fieldPresentation":{"boundary":{"blocks":[{"title":"数据与知觉的条件"},{"from":" 网页演示的2秒终点","role":"demo"}]}}},{"q":18,"chapter":7,"section":"7.1","type":"单选","topic":"流媒体","title":"流媒体强调边传输边播放和连续时序","trigger":"题目要求辨认不属于流媒体典型特征的属性。","conclusion":"流媒体的核心是边接收边播放，无须等整个文件下载完成；压缩是常用的减小传输量手段，并非流式传输必须具备的条件。","points":["流媒体既可以用于直播，也可以用于点播；“流式”描述传输与播放方式，不等于内容一定在现场实时产生。","播放器通常先积累一段可播放数据作为缓冲，用来吸收网络速度波动；缓冲耗尽而新数据未及时到达时，可能卡顿或暂停等待。","压缩可降低传输所需的数据量，但网络也能传输未压缩音频流，例如 RTP 的 L16 PCM 音频。","是否流式传输、使用何种编码、是否加密，是三个不同问题；机密性需要相应的加密与访问控制，不能由“流媒体”一词推出。","数字文件逐字节正确复制不会自行降低画质或音质；重新使用有损编码转码，才可能再损失信息。"],"boundary":"“可边下边播”不保证任何网络下都不卡顿，也不等于可以立即跳到任意尚未获取的位置；跳转能力还取决于媒体组织、服务器支持和播放器实现。","id":"y2023q18","sources":[{"year":2023,"q":18,"type":"单选"},{"year":2022,"q":18,"type":"单选"}],"keys":["2023-18","2022-18"],"related":[{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"网络的实际有效速率和波动决定缓冲能否及时补充，标称带宽本身不能保证播放不卡顿。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"流式播放、压缩编码和容器是不同维度；逐字节复制与再次有损转码也应分别判断。"}],"pointGroups":[{"title":"直播、点播与播放缓冲","indices":[0,1]},{"title":"分开判断压缩、加密与复制转码","indices":[2,3,4]}]},{"q":18,"chapter":7,"section":"7.1","type":"单选","topic":"媒体格式","title":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","trigger":"真题从图像动画能力、常见媒体格式和能否精确恢复原数据考查压缩。","conclusion":"无损压缩保证解码后恢复被编码的数据；它不能修复编码前已经发生的缩放、降色或其他信息损失。判断格式时，还要区分媒体内容、编码方式和容器。","points":["无损是数据可逐位恢复，不是肉眼看着差不多；有损压缩则不能保证还原被编码前的全部数据。","PNG 使用无损压缩；但若保存前已把照片缩小或减少颜色，丢失的信息不会因存成 PNG 而恢复。","GIF 支持多帧动画，使用调色板索引和无损压缩；单个调色板最多 256 色。把高色彩图像转成 GIF 时，降色过程可能先产生损失。","静态 PNG 保存一幅图像；APNG 支持动画，已纳入 W3C PNG 第三版。JPEG 和 MP3 的常见使用方式分别是有损图像编码和有损音频编码。","WAV 是音频容器，常见内容为未压缩 PCM，也可以承载压缩音频；不能把 WAV 一概说成未压缩。","MIDI 保存演奏事件而非录音波形。比较文件大小前，应确认比较的是否是同一种媒体、相同时长或尺寸，以及相同编码条件。","先问“存什么”，再问“怎样编码”：BMP常见为未压缩位图，也支持游程压缩；TIFF的压缩方式取决于设置；SVG可描述矢量对象并嵌入位图。JPEG通常用于照片，PNG适合需要无损像素或透明的图像；是否合适取决于内容、大小及输出要求，不能无条件排名。","MP4、AVI、MOV主要是音视频封装，可包含不同编码的数据；H.264是视频编码的例子。WMV既用于视频编码系列名称，也常作ASF封装文件的扩展名。文件名后缀不能独立证明内部编码或是否无损。","本页约定压缩比=原始数据量÷压缩后数据量：1000 B变成250 B是4∶1，压缩后占25%，节省75%。遇到“压缩率”先看题目给出的定义；这些量只描述大小关系，不直接证明画质或能否还原。","旧题语境要单独判断：2020年第18题把传统静态PNG与GIF动画比较；不能由此否认APNG。2021年第16题的WAV选项按常见PCM录音理解；WAV容器可装压缩音频，MIDI也不是把录音波形压小后的同义词。"],"boundary":"“无损压缩”只描述编码与解码这一步。GIF 的颜色上限按调色板理解，不应把多帧动画中可能使用的全部颜色都绝对限定为同一组 256 色。","id":"merged-14","sources":[{"year":2020,"q":18,"type":"单选"},{"year":2023,"q":48,"type":"填空"},{"year":2026,"q":23,"type":"多选"},{"year":2021,"q":16,"type":"单选","page":4}],"keys":["2020-18","2023-48","2026-23","2021-16"],"comparison":{"headers":["格式或技术","通常保存什么","判断要点"],"rows":[["PNG / APNG","静态 / 动态位图","无损编码不逆转此前的编辑损失"],["GIF","索引色位图或动画","压缩无损；转为索引色可能降色"],["JPEG / MP3","图像 / 音频","常见方式为有损编码"],["WAV","音频容器内的音频数据","常见 PCM，也能装压缩音频"],["MIDI","音符、力度等演奏事件","不是录音波形"],["BMP / TIFF","位图","不能只凭后缀判断是否压缩或是否有损"],["SVG","矢量描述，也能嵌位图","路径缩放性质不自动覆盖内嵌照片"],["MP4 / AVI / MOV","音视频容器","内部采用何种编码需要另查"]]},"related":[{"id":"y2024q32","label":"采样、位深、编码与冗余共同决定数字媒体数据量","reason":"用PCM、压缩音频和MIDI的表示方式进一步区分录音波形、演奏事件、编码和容器。"},{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"PNG或GIF采用无损压缩，仍不能消除保存前的缩放、降色损失；像素与位深决定被编码的数据。"},{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"选择图像格式前先区分矢量对象与像素阵列，避免把无损压缩误认为任意放大都不失真。"}],"pointGroups":[{"title":"无损保证的范围","indices":[0,8]},{"title":"图像格式与编辑前置损失","indices":[1,2,3,6]},{"title":"音视频容器和历史题语境","indices":[4,5,7,9]}],"pointPresentation":{"0":{"title":"先看可逆性","navigationLabel":"先看可逆性"},"6":{"title":"按内容与用途选择图像格式","navigationLabel":"按内容与用途选择图像格式"},"7":{"title":"容器和编码分层判断","navigationLabel":"容器和编码分层判断"},"8":{"title":"压缩比、剩余比例与节省比例","navigationLabel":"压缩比、剩余比例与节省比例"},"9":{"title":"保留旧题条件，不照搬泛化解析","navigationLabel":"保留旧题条件，不照搬泛化解析"}}},{"id":"syllabus-media-edit-export","chapter":7,"section":"7.2","origin":"syllabus","topic":"多媒体系统与软件","title":"多媒体系统与常用软件：从采集、编辑到导出","conclusion":"多媒体系统由硬件与软件协同完成采集、处理、存储和输出；软件按任务选用，工程文件与最终导出文件承担不同目的。","points":["音频教学示例：在Audacity中选取需要保留的录音范围，预听后通过导出音频选择文件名、位置、WAV或MP3等格式；按要求确认声道和编码参数。多轨导出时可以混合成一个单声道或立体声文件。","视频教学示例：在Premiere时间线选中要输出的序列→文件→导出→媒体，核对格式、分辨率、帧率和保存位置；导出后重新播放，检查起止画面和音画同步。","需要回头改片段顺序时保留工程与必要素材；只交付成片时导出媒体文件。把工程文件改成.mp4扩展名不会生成视频。","系统可沿输入/采集→处理→存储→输出理解：麦克风、摄像头、扫描仪取得不同素材；CPU、内存及相关图形/音频处理设备配合软件加工；存储设备保存数据；显示器、音箱呈现结果。同一系统可以贯穿多个环节。","分清硬件与软件：声卡或音频接口负责相应输入输出，显卡承担图形显示/处理任务；驱动帮助操作系统与设备协作，编辑应用负责内容操作。并非每台多媒体计算机都必须另装独立声卡、显卡或采集卡。","按任务认识常用软件：Photoshop用于图像处理，Audacity/Audition用于音频编辑，Premiere用于视频剪辑，Flash/Animate可用于动画制作；播放器负责呈现媒体，多媒体集成工具把素材与交互组织为作品。一个应用可跨多个任务，软件名字不是文件格式。","音频操作先取得或导入录音→选定范围、试听并剪除无关段落→调整需要的内容→保存可继续编辑的工程→导出指定格式→重新播放核对时长、声道和声音。要只导出选区时检查导出范围，不能仅凭选区高亮认定导出结果。","视频操作先导入素材→放入时间线→裁定起止并安排片段顺序→预览音画→保留工程和所需素材→导出成片。工程通常保存编辑组织信息，能否包含全部素材取决于软件与保存方式；移动外部素材后可能需要重新定位。","考试中的旧软件名保留原语境：Flash动画制作软件、Flash Player播放插件与动画文件是不同对象。不要因为旧播放器停止支持，就把历年题中“Flash用于动画制作”改成错误；本节不要求安装旧插件。"],"boundary":"2026考纲要求了解常用音频、图像、视频软件的使用方法，未指定Photoshop等软件版本。这里以桌面软件作流程示例，菜单位置可能随版本变化；未进行原生软件实测。","sources":[],"trigger":"先辨认系统各环节及软件任务，再决定保存工作工程还是交付媒体成品。","related":[{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"对照相邻概念，检查作用范围"},{"id":"syllabus-image-editing","label":"图像编辑操作链","reason":"系统与软件任务建立后，用图层、尺寸和输出完成一条图像处理任务。"}],"pointGroups":[{"title":"系统与设备职责","indices":[3,4]},{"title":"按任务选软件","indices":[5,8]},{"title":"音视频编辑到交付","indices":[6,0,7,1,2]}],"pointPresentation":{"2":{"title":"工程文件不等于成片","navigationLabel":"工程文件不等于成片"},"3":{"title":"采集、处理、存储与输出","navigationLabel":"采集、处理、存储与输出"},"4":{"title":"硬件、驱动与应用分工","navigationLabel":"硬件、驱动与应用分工"},"5":{"title":"软件按任务分类","navigationLabel":"软件按任务分类"},"6":{"title":"音频范围、试听与导出","navigationLabel":"音频范围、试听与导出"},"7":{"title":"视频素材、时间线与工程","navigationLabel":"视频素材、时间线与工程"},"8":{"title":"旧软件名称保留考试语境","navigationLabel":"旧软件名称保留考试语境"}},"comparison":{"headers":["环节","典型设备或软件任务","不能混淆"],"rows":[["采集","麦克风录音、摄像头取景、扫描仪取图","输入设备不是编辑应用"],["处理","剪辑、调色、编码、混音","编码/解码功能与容器文件不同"],["存储","保存工程、素材及导出媒体","保存工程不保证已生成可播放成片"],["输出","显示器/音箱配合播放软件","播放不等于内容可继续分层编辑"]]}},{"id":"syllabus-image-editing","chapter":7,"section":"7.3","type":"知识补充","topic":"图像编辑基础","title":"图像编辑先确定图层与选区，再调整尺寸、效果和输出","trigger":"要裁去边缘、改变像素尺寸、增加画布或保留可编辑副本时，先确认作用对象。","conclusion":"图层组织内容，选区限定局部；重新采样、画布大小和裁剪解决不同任务。以Photoshop桌面版为例建立操作链，保存工作文件后再按用途导出。","origin":"syllabus","sources":[],"keys":[],"points":["先打开图像并保留工作副本，查看图层面板。不同图层分别承载内容，当前选中的目标层决定许多操作的对象；隐藏一层只改变可见性，不等于删除该层。需要局部处理时，再用选区工具圈定范围。","选区限定准备处理的区域，选中本身不会裁剪图片或新建图层。检查目标层和选区后再移动、复制、调整或应用滤镜；取消选区只是解除局部范围限制，不会自动撤销已经应用的编辑。","要改变整幅图像的像素尺寸：图像→图像大小→检查单位与比例锁定→启用重新采样→输入目标宽高并预览→确定。重新采样会增删像素；增加像素数依靠插值，不能保证恢复原本没有记录的真实细节。","只改变打印尺寸时，在图像大小中关闭重新采样，再调整PPI或打印宽高；原像素尺寸保持。相同1200×800像素改成不同PPI，只改变像素与纸面长度的对应，不等于增加图像数据。","要增加边缘空间：图像→画布大小→指定宽高、单位及锚点→确定。扩大画布不把原主体等比放大；缩小画布会裁入图像。新增区是否透明或填色取决于背景等设置，锚点决定保留内容的位置。","裁剪工具用于确定保留的构图区域；检查裁剪框后确认。是否删除外围像素取决于“删除裁剪的像素”等选项。自由变换则对所选内容缩放或旋转，先检查对象与比例锁定；不背跨版本通用的Shift约束口诀。","颜色或明暗不合适时，可按目标使用亮度/对比度、色相/饱和度等调整。调整图层保留可再修改的调整信息，与直接改写像素不同。滤镜用于校正或产生效果，先确认目标层/选区，再调整参数；可预览的对话框中比较前后，不需要的草稿用取消退出。","先保存能继续编辑的工作文件，例如保留图层的PSD；再按交付要求导出副本并核对尺寸、透明和质量。JPEG常用于照片，PNG可保留透明像素；普通导出图片不等于完整图层工程，PSD也不是唯一可能保留图层的格式。","完整小例：把800×600像素照片按比例缩到400×300，用图像大小并启用重新采样；需要在右侧增加100像素空白，改画布宽为500、锚点靠左。结果为500×300画布、原缩小主体仍为400×300；保存工作版本后导出并检查。"],"boundary":"这是常用图像处理方法的教学组织，不声称考纲指定某一Photoshop版本。网页演示只模拟最近邻重新采样与固定左上锚点的画布裁扩，不模拟完整图层、色彩管理或真实文件保存。","pointGroups":[{"title":"先确定操作范围","indices":[0,1]},{"title":"尺寸与构图使用不同命令","indices":[2,3,4,5]},{"title":"调整、保存与完整任务","indices":[6,7,8]}],"pointPresentation":{"0":{"title":"图层先决定对象","navigationLabel":"图层先决定对象"},"1":{"title":"选区不是裁剪","navigationLabel":"选区不是裁剪"},"2":{"title":"图像大小与重新采样","navigationLabel":"图像大小与重新采样"},"3":{"title":"只改打印尺寸","navigationLabel":"只改打印尺寸"},"4":{"title":"画布大小与锚点","navigationLabel":"画布大小与锚点"},"5":{"title":"裁剪与变换","navigationLabel":"裁剪与变换"},"6":{"title":"调整和滤镜的作用范围","navigationLabel":"调整和滤镜的作用范围"},"7":{"title":"工作文件和导出副本","navigationLabel":"工作文件和导出副本"},"8":{"title":"缩小主体后增加右侧空白","navigationLabel":"缩小主体后增加右侧空白"}},"comparison":{"headers":["任务","入口或机制","结果与限制"],"rows":[["改变整图像素尺寸","图像大小＋重新采样","增删像素，不保证补回真实细节"],["只改纸面大小","图像大小，关闭重新采样","PPI与打印尺寸互相改变，像素数不变"],["增加外边或缩减画布","画布大小","原主体不等比缩放；缩小时可能裁入内容"],["保留某部分构图","裁剪","结果受保留/删除外围像素等选项影响"]]},"searchAliases":["Photoshop","PS","图像大小","画布大小","重新采样","图层","选区","裁剪","PSD"],"related":[{"id":"y2020q27","label":"像素尺寸、PPI与数据量","reason":"图像大小操作依赖像素数和打印尺寸的区别。"},{"id":"y2020q17","label":"颜色模式选择","reason":"需要转换RGB或CMYK时核对用途和颜色范围。"},{"id":"y2024q43","label":"锐化及结果限制","reason":"滤镜具体例子回到边缘对比与真实细节的区别。"}],"fieldPresentation":{"boundary":{"blocks":[{"title":"软件版本语境"},{"from":"网页演示只模拟","role":"demo"}]}}},{"q":17,"chapter":7,"section":"7.3","type":"单选","topic":"颜色模式","title":"RGB与CMYK的适用场景","trigger":"题目询问新建图像文档常见的默认颜色模式。","conclusion":"面向屏幕显示的新建图像通常使用RGB；印刷工作常使用CMYK。","points":["RGB是红、绿、蓝光的加色模型。每通道8位时，(0,0,0)为黑、(255,255,255)为白、(255,0,0)为红；三通道数值相等时呈中性灰。","CMYK是青、品红、黄、黑的印刷减色模型；墨层吸收部分入射光，纸面反射剩余光进入眼睛。在白纸上四种墨量均为0时露出纸白。","灰度模式只记录明暗层次，不保存完整彩色信息；8位灰度有2⁸=256个可表示灰度值，与RGB每通道8位、每像素共24位不同。","改颜色模式前先明确用途并保留副本。在Photoshop的图像→模式中查看当前模式，再按交付需要转换；RGB与CMYK的可表现颜色范围和转换结果受颜色配置、设备及印刷条件影响，不是给三个通道机械换成四个就保证颜色完全不变。"],"boundary":"软件默认值可能随预设和用途变化，不能把“永远默认RGB”当绝对规则；应结合屏幕或印刷目的。","id":"y2020q17","sources":[{"year":2020,"q":17,"type":"单选"}],"keys":["2020-17"],"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"RGB的三个颜色通道与Alpha透明度通道要分开理解，不能把RGBA的32位全部说成RGB颜色数。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"颜色表示可能在保存前发生转换或降色；之后采用无损压缩也不会恢复此前丢失的信息。"}],"pointGroups":[{"title":"颜色模型与通道","indices":[0,1,2]},{"title":"模式转换的操作边界","indices":[3]}],"pointPresentation":{"0":{"title":"RGB加色与通道值","navigationLabel":"RGB加色与通道值"},"1":{"title":"CMYK减色与纸白","navigationLabel":"CMYK减色与纸白"},"3":{"title":"先定用途再转换模式","navigationLabel":"先定用途再转换模式"}}},{"q":43,"chapter":7,"section":"7.3","type":"填空","topic":"图像处理","title":"锐化增强边缘和局部细节","trigger":"题目要求填写使模糊图像边缘更清晰的常见处理。","conclusion":"锐化通过增强高频成分或边缘对比，使轮廓和局部细节更突出。","points":["锐化不能真正恢复从未记录下来的细节。","过度锐化会放大噪声并产生光晕。","模糊通常抑制高频成分，适合降噪或柔化。","操作时先选目标图层，需要局部锐化再建立选区；进入相应锐化滤镜或工具，调节强度并观察细节、噪声和光晕。可预览时比较修改前后，满意再确定，不满意取消；已经确定的直接编辑需用撤销等方式恢复。"],"boundary":"锐化改善视觉清晰感，不等于提高原始分辨率；严重失焦或运动模糊需要更复杂的复原方法。","id":"y2024q43","sources":[{"year":2024,"q":43,"type":"填空"}],"keys":["2024-43"],"related":[{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"矢量缩放可重新计算边界，位图锐化则处理已有像素，二者改善清晰程度的机制不同。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"增强视觉清晰感不等于恢复原始数据，可与无损压缩只保证编码阶段可逆的边界对照。"},{"id":"syllabus-image-editing","label":"先确定图层和选区","reason":"局部锐化先明确被编辑的对象和范围。"}],"pointGroups":[{"title":"先理解锐化和模糊","indices":[0,1,2]},{"title":"选择范围并核对结果","indices":[3]}],"pointPresentation":{"0":{"title":"锐化不能补回缺失细节","navigationLabel":"锐化不能补回缺失细节"},"3":{"title":"锐化前确认图层与选区","navigationLabel":"锐化前确认图层与选区"}}}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
