window.NOTE_DEMOS={"y2026q4":{"kind":"explore","title":"观察多媒体的四个特征","task":"点击系统行为，判断它体现哪种特征。","initial":"多媒体把多种数字媒体组织为统一体验。","actions":[{"label":"文字＋声音＋视频同屏","stage":"集成性与多样性","result":"多种媒体被统一处理和呈现。","tone":"good"},{"label":"用户点击改变内容","stage":"交互性","result":"用户行为会影响系统反馈。","tone":"good"},{"label":"视频会议即时响应","stage":"实时性","result":"采集、传输和处理需要及时完成。","tone":"good"},{"label":"只允许单一信息形式","stage":"单一性","result":"与多媒体核心含义相反。","tone":"bad"}]},"y2020q27":{"kind":"explore","title":"内容还是载体？","task":"点击对象，观察它属于媒体元素还是存储设备。","initial":"媒体元素是信息表现形式，载体负责保存它们。","actions":[{"label":"文字、图像、声音","stage":"媒体元素","result":"直接承担信息表达。","tone":"good"},{"label":"动画、视频","stage":"媒体元素","result":"由连续画面、声音等组织形成。","tone":"good"},{"label":"硬盘、U盘","stage":"存储载体","result":"能保存媒体文件，但自身不是媒体元素。","tone":"warn"}]},"y2020q17":{"kind":"explore","title":"屏幕与印刷切换颜色模式","task":"点击输出目的，观察应优先使用RGB还是CMYK。","initial":"颜色模式要跟最终输出介质匹配。","actions":[{"label":"手机和显示器","stage":"RGB","result":"通过红、绿、蓝光的加色混合显示颜色。","tone":"good"},{"label":"四色印刷","stage":"CMYK","result":"使用青、品红、黄、黑油墨的减色体系。","tone":"good"},{"label":"RGB直接印刷","stage":"颜色可能发生偏差","result":"屏幕发光色域与油墨呈色范围不同。","tone":"warn"}]},"y2024q43":{"kind":"explore","title":"比较锐化强度，看边缘与噪声一起变化","task":"比较三档示意效果；这里不计算真实图像处理强度或新增像素。","initial":"原图略显柔和，但噪声较低。","actions":[{"label":"原图","stage":"边缘自然","result":"没有额外高频增强。","tone":"good"},{"label":"适度锐化","stage":"轮廓更清晰","result":"细节感增强且光晕不明显。","tone":"good"},{"label":"过度锐化","stage":"噪声与白边明显","result":"清晰感开始变成伪影。","tone":"bad"},{"label":"锐化=提高分辨率","stage":"错误","result":"无法创造原图未记录的真实细节。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"y2026q4":{"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"VR把多感知、交互与实时反馈组合起来，但普通多媒体或3D画面不因此自动成为VR。","chapter":9},{"id":"y2020q38","label":"帧、帧率与视频连续感","reason":"连续音视频体现实时性；帧与帧率笔记提供区分连续播放要求和媒体种类多少的实例。","chapter":7}],"topics":[]},"y2023q19":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"位图放大受固定像素阵列约束，可进一步从像素数和每像素位数理解图像表示。","chapter":7},{"id":"y2024q43","label":"锐化增强边缘和局部细节","reason":"位图放大或缺少细节后，锐化只能增强边缘清晰感，不能把缺失像素信息变回来。","chapter":7}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"y2020q27":{"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"像素数据量计算要将每像素位数转换为字节，并按题设区分MB与MiB。","chapter":1},{"id":"y2020q17","label":"RGB与CMYK的适用场景","reason":"RGB通道参与颜色表示，CMYK面向印刷；颜色模型与每通道位深是不同判断维度。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"实际文件还受压缩和容器影响，不能把宽×高×位深的原始像素量直接当作JPEG或PNG文件大小。","chapter":7}],"topics":[]},"y2024q32":{"related":[{"id":"merged-3","label":"bit、Byte、像素与存储容量单位","reason":"采样率乘位深和声道数得到bit/s，乘时长后还要除以8才能换成B。","chapter":1},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"PCM原始数据公式、MP3平均码率估算和WAV容器判断必须分别使用，MIDI也不是录音波形。","chapter":7},{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"算出音频码率和数据量后，可将其作为网络传输计算的输入，同时区分媒体码率与链路有效速率。","chapter":6}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"y2020q38":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"先估算一帧的像素数据，再结合帧率与时长理解未压缩视频数据量的增长。","chapter":7},{"id":"y2023q18","label":"流媒体强调边传输边播放和连续时序","reason":"帧的连续播放需要数据及时到达；流媒体缓冲可解释帧率之外的网络卡顿原因。","chapter":7}],"topics":[]},"y2023q18":{"related":[{"id":"y2020q26","label":"带宽、吞吐量、时延与单位","reason":"网络的实际有效速率和波动决定缓冲能否及时补充，标称带宽本身不能保证播放不卡顿。","chapter":6},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"流式播放、压缩编码和容器是不同维度；逐字节复制与再次有损转码也应分别判断。","chapter":7}],"topics":[]},"merged-14":{"related":[{"id":"y2024q32","label":"采样、位深、编码与冗余共同决定数字媒体数据量","reason":"用PCM、压缩音频和MIDI的表示方式进一步区分录音波形、演奏事件、编码和容器。","chapter":7},{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"PNG或GIF采用无损压缩，仍不能消除保存前的缩放、降色损失；像素与位深决定被编码的数据。","chapter":7},{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"选择图像格式前先区分矢量对象与像素阵列，避免把无损压缩误认为任意放大都不失真。","chapter":7}],"topics":[{"id":"cmp-media-representation-size","title":"表示与容量：字符、字形、像素、编码和容器"}]},"syllabus-media-edit-export":{"related":[{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"对照相邻概念，检查作用范围","chapter":7},{"id":"syllabus-image-editing","label":"图像编辑操作链","reason":"系统与软件任务建立后，用图层、尺寸和输出完成一条图像处理任务。","chapter":7}],"topics":[]},"syllabus-image-editing":{"related":[{"id":"y2020q27","label":"像素尺寸、PPI与数据量","reason":"图像大小操作依赖像素数和打印尺寸的区别。","chapter":7},{"id":"y2020q17","label":"颜色模式选择","reason":"需要转换RGB或CMYK时核对用途和颜色范围。","chapter":7},{"id":"y2024q43","label":"锐化及结果限制","reason":"滤镜具体例子回到边缘对比与真实细节的区别。","chapter":7}],"topics":[]},"y2020q17":{"related":[{"id":"y2020q27","label":"多媒体元素、数字图像与颜色深度","reason":"RGB的三个颜色通道与Alpha透明度通道要分开理解，不能把RGBA的32位全部说成RGB颜色数。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"颜色表示可能在保存前发生转换或降色；之后采用无损压缩也不会恢复此前丢失的信息。","chapter":7}],"topics":[]},"y2024q43":{"related":[{"id":"y2023q19","label":"矢量图形放大通常不失真，位图由像素构成","reason":"矢量缩放可重新计算边界，位图锐化则处理已有像素，二者改善清晰程度的机制不同。","chapter":7},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"增强视觉清晰感不等于恢复原始数据，可与无损压缩只保证编码阶段可逆的边界对照。","chapter":7},{"id":"syllabus-image-editing","label":"先确定图层和选区","reason":"局部锐化先明确被编辑的对象和范围。","chapter":7}],"topics":[]}};
